// Extrae el texto limpio de la nota desde el bloque structured-data (ld+json) de Infobae.
const html = $input.first().json.data;

// Buscar todos los bloques <script type="application/ld+json">
const regex = /<script type="application\/ld\+json">(.*?)<\/script>/gs;
let match;
let articleBody = null;

while ((match = regex.exec(html)) !== null) {
  try {
    const json = JSON.parse(match[1]);
    // El bloque que nos interesa es el de tipo NewsArticle, que tiene articleBody.
    if (json.articleBody) {
      articleBody = json.articleBody;
      break;
    }
  } catch (e) {
    // Si un bloque no parsea, seguir con el siguiente.
    continue;
  }
}

if (!articleBody) {
  throw new Error("No se encontró articleBody en la nota.");
}

return [
  {
    json: {
      texto_nota: articleBody,
    },
  },
];
